var html = $input.first().json.data || '';
var text = html.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
var lower = text.toLowerCase();

var today = new Date();
var fecha = today.toLocaleDateString('es-AR', { weekday: 'long', day: 'numeric', month: 'long' });

var tipoDia = 'fruto';
if (lower.includes('raíz') || lower.includes('raiz')) tipoDia = 'raíz';
else if (lower.includes('flor')) tipoDia = 'flor';
else if (lower.includes('hoja')) tipoDia = 'hoja';

var faseLunar = 'cuarto creciente';
if (lower.includes('luna nueva')) faseLunar = 'luna nueva';
else if (lower.includes('luna llena')) faseLunar = 'luna llena';
else if (lower.includes('menguante')) faseLunar = 'cuarto menguante';

return [{ json: { fecha: fecha, tipoDia: tipoDia, faseLunar: faseLunar, textoPagina: text.substring(0, 400) } }];

