        },
        {
          role: 'user',
          content: 'Escribe una narración para un video de Instagram/TikTok de 35 segundos (máximo 80 palabras). Segunda persona, sin hashtags, sin emojis. Conectada con la naturaleza y el cosmos.\n\nFecha: ' + fecha + '\nDía biodinámico: ' + tipoDia + '\nFase lunar: ' + faseLunar + '\n\nEscribe SOLO la narración.'
        }
      ]
    }
  }
}];

var libreto = $json.libreto;

return [{
  json: {
    libreto: libreto,
    elevenBody: {
      text: libreto,
      model_id: 'eleven_multilingual_v2',
      voice_settings: { stability: 0.45, similarity_boost: 0.80 }
    }
  }
}];

var item = $input.first();
var bin = item.binary && item.binary.audio ? item.binary.audio : null;
if (!bin) throw new Error('No se encontró el binario audio en ElevenLabs Voz');

return [{
  json: item.json,
  binary: {
    audio: {
      data: bin.data,
      mimeType: 'audio/mpeg',
      fileType: 'audio',
      fileExtension: 'mp3',
      fileName: 'audio.mp3'
    }
  }
}];

