var faseLunar = $node['Parsear Datos'].json.faseLunar;
var libreto = $node['Extraer Libreto'].json.libreto;

if (!audioUrl) throw new Error('Cloudinary audio: secure_url no encontrada. $json: ' + JSON.stringify($json));

var coloresFondo = {
  'raíz': '#120804',
  'flor': '#1e0828',
  'hoja': '#041208',
  'fruto': '#1e0800'
};
var fondo = coloresFondo[tipoDia] || '#0a0a0a';

var DUR = 9;
var TOTAL = DUR * 4;

var htmlOverlay = '<div style="font-family:Georgia,serif;color:white;text-align:center;padding:20px;text-shadow:0 2px 16px rgba(0,0,0,0.99)"><p style="font-size:28px;margin:0 0 10px;letter-spacing:2px;font-weight:normal;text-transform:uppercase">' + fecha + '</p><p style="font-size:19px;margin:0;letter-spacing:5px;opacity:0.85;text-transform:uppercase">Día ' + tipoDia + ' · ' + faseLunar + '</p></div>';

var payload = {
  timeline: {
    background: fondo,
    tracks: [
      {
        clips: [{
          asset: { type: 'html', html: htmlOverlay, width: 540, height: 200 },
          start: 0,
          length: TOTAL,
          position: 'bottom',
          offset: { x: 0, y: -0.05 }
        }]
      },
      {
        clips: [{
          asset: { type: 'audio', src: audioUrl, volume: 1, effect: 'fadeIn' },
          start: 0,
          length: TOTAL
        }]
      }
    ]
  },
  output: { format: 'mp4', resolution: 'sd', aspectRatio: '9:16', fps: 25 }
};

return [{ json: { payload: payload, payloadStr: JSON.stringify(payload), libreto: libreto, fecha: fecha, tipoDia: tipoDia } }];

